#include <stdio.h>
#include <stdlib.h>

#define MAX_VERTICES 8

int adj[MAX_VERTICES][MAX_VERTICES];
int indegree[MAX_VERTICES];
int done[MAX_VERTICES];

void topological_sort(int num_vertices, char **edges) {
    int i, j, k;
    int vertex, neighbor;

    // Initialize adjacency matrix and indegree array
    for (i = 0; i < num_vertices; i++) {
        for (j = 0; j < num_vertices; j++) {
            adj[i][j] = 0;
        }
        indegree[i] = 0;
    }

    // Build adjacency matrix and update indegree array
    for (i = 0; i < num_vertices; i++) {
        vertex = atoi(edges[i * 2]);
        neighbor = atoi(edges[i * 2 + 1]);
        adj[vertex][neighbor] = 1;
        indegree[neighbor]++;
    }

    // Perform topological sorting
    int queue[MAX_VERTICES];
    int queue_size = 0;
    for (i = 0; i < num_vertices; i++) {
        if (indegree[i] == 0) {
            queue[queue_size++] = i;
        }
    }

    while (queue_size > 0) {
        vertex = queue[--queue_size];
        printf("%d ", vertex);
        for (j = 0; j < num_vertices; j++) {
            if (adj[vertex][j] == 1) {
                indegree[j]--;
                if (indegree[j] == 0) {
                    queue[queue_size++] = j;
                }
            }
        }
    }

    // Check for cycles
    for (i = 0; i < num_vertices; i++) {
        if (indegree[i] != 0) {
            printf("CYCLE\n");
            return;
        }
    }
}

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("INVALID_INPUT\n");
        return 1;
    }

    int num_vertices = (argc - 1) / 2;
    topological_sort(num_vertices, argv + 1);

    return 0;
}
